CREATE TABLE demo_metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL) STRICT;
CREATE TABLE organizations (id TEXT PRIMARY KEY, name TEXT NOT NULL, definition_hash TEXT NOT NULL) STRICT;
CREATE TABLE actors (id TEXT PRIMARY KEY, name TEXT NOT NULL, audience TEXT NOT NULL CHECK(audience IN ('CUSTOMER','STAFF')), active INTEGER NOT NULL CHECK(active IN (0,1)), definition_hash TEXT NOT NULL) STRICT;
CREATE TABLE memberships (actor_id TEXT NOT NULL REFERENCES actors(id), organization_id TEXT NOT NULL REFERENCES organizations(id), role TEXT NOT NULL CHECK(role IN ('OWNER','REQUESTER','VIEWER')), can_select_offers INTEGER NOT NULL CHECK(can_select_offers IN (0,1)), active INTEGER NOT NULL CHECK(active IN (0,1)), definition_hash TEXT NOT NULL, PRIMARY KEY(actor_id,organization_id)) STRICT;
CREATE TABLE sessions (cookie_hash TEXT PRIMARY KEY, audience TEXT NOT NULL CHECK(audience IN ('PUBLIC','CUSTOMER','STAFF')), actor_id TEXT REFERENCES actors(id), organization_id TEXT REFERENCES organizations(id), context_generation INTEGER NOT NULL CHECK(context_generation>0), context_token TEXT NOT NULL, csrf_token TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), created_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, expires_at TEXT NOT NULL, CHECK((audience='PUBLIC' AND actor_id IS NULL AND organization_id IS NULL) OR (audience='CUSTOMER' AND actor_id IS NOT NULL) OR (audience='STAFF' AND actor_id IS NOT NULL AND organization_id IS NULL))) STRICT;
CREATE TABLE discovery_items (id TEXT PRIMARY KEY, definition_json TEXT NOT NULL CHECK(json_valid(definition_json)), definition_hash TEXT NOT NULL) STRICT;
CREATE TABLE evidence_versions (item_id TEXT NOT NULL REFERENCES discovery_items(id), evidence_version TEXT NOT NULL, snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)), definition_hash TEXT NOT NULL, PRIMARY KEY(item_id,evidence_version)) STRICT;
CREATE TABLE service_requests (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, organization_id TEXT NOT NULL REFERENCES organizations(id), original_actor_id TEXT NOT NULL REFERENCES actors(id), original_contact_json TEXT NOT NULL CHECK(json_valid(original_contact_json)), submitted_at TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('Submitted','In review','Needs information','Quote ready','Accepted','Scheduled','Delivered')), aggregate_version INTEGER NOT NULL CHECK(aggregate_version>0), current_brief_revision INTEGER NOT NULL CHECK(current_brief_revision>0), matching_state TEXT NOT NULL CHECK(matching_state IN ('Preliminary check ready','Automatic check unavailable')), UNIQUE(id,organization_id)) STRICT;
CREATE TABLE brief_revisions (request_id TEXT NOT NULL, organization_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), brief_json TEXT NOT NULL CHECK(json_valid(brief_json)), evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json)), created_at TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), PRIMARY KEY(request_id,revision), FOREIGN KEY(request_id,organization_id) REFERENCES service_requests(id,organization_id)) STRICT;
CREATE TABLE request_events (id TEXT PRIMARY KEY, request_id TEXT NOT NULL, organization_id TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), type TEXT NOT NULL, occurred_at TEXT NOT NULL, message TEXT NOT NULL, FOREIGN KEY(request_id,organization_id) REFERENCES service_requests(id,organization_id)) STRICT;
CREATE TABLE command_reviews (token_hash TEXT PRIMARY KEY, command_name TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), audience TEXT NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id), context_generation INTEGER NOT NULL, context_token_hash TEXT NOT NULL, fingerprint TEXT NOT NULL, expires_at TEXT NOT NULL, consumed_at TEXT) STRICT;
CREATE TABLE action_receipts (command_id TEXT PRIMARY KEY, command_name TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES actors(id), audience TEXT NOT NULL, organization_id TEXT NOT NULL REFERENCES organizations(id), context_generation INTEGER NOT NULL, context_token_hash TEXT NOT NULL, fingerprint TEXT NOT NULL, outcome_json TEXT NOT NULL CHECK(json_valid(outcome_json)), committed_at TEXT NOT NULL) STRICT;
CREATE TRIGGER brief_no_update BEFORE UPDATE ON brief_revisions BEGIN SELECT RAISE(ABORT,'Brief revisions are immutable'); END;
CREATE TRIGGER brief_no_delete BEFORE DELETE ON brief_revisions BEGIN SELECT RAISE(ABORT,'Brief revisions are immutable'); END;
CREATE TRIGGER events_no_update BEFORE UPDATE ON request_events BEGIN SELECT RAISE(ABORT,'Request history is append-only'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON request_events BEGIN SELECT RAISE(ABORT,'Request history is append-only'); END;
CREATE TRIGGER receipts_no_update BEFORE UPDATE ON action_receipts BEGIN SELECT RAISE(ABORT,'Successful receipts are immutable'); END;
CREATE TRIGGER receipts_no_delete BEFORE DELETE ON action_receipts BEGIN SELECT RAISE(ABORT,'Successful receipts are immutable'); END;
CREATE TRIGGER request_identity_no_change BEFORE UPDATE ON service_requests WHEN NEW.reference<>OLD.reference OR NEW.organization_id<>OLD.organization_id OR NEW.original_actor_id<>OLD.original_actor_id OR NEW.original_contact_json<>OLD.original_contact_json OR NEW.submitted_at<>OLD.submitted_at BEGIN SELECT RAISE(ABORT,'Original request identity is immutable'); END;
CREATE INDEX requests_by_org ON service_requests(organization_id,submitted_at DESC,id);
CREATE INDEX events_by_request ON request_events(request_id,occurred_at,id);
